@[simp] theorem tensorProductLinearMap_tmul {X X' : ModuleCat.{u} A₁}
    {Y Y' : ModuleCat.{u} A₂} (f : X ⟶ X') (g : Y ⟶ Y') (m₁ : X) (m₂ : Y) :
    tensorProductLinearMap k f g (m₁ ⊗ₜ[k] m₂) = f.hom m₁ ⊗ₜ[k] g.hom m₂

@[simp] theorem tensorProductMap_hom {X X' : ModuleCat.{u} A₁} {Y Y' : ModuleCat.{u} A₂}
    (f : X ⟶ X') (g : Y ⟶ Y') :
    (tensorProductMap k f g).hom = tensorProductLinearMap k f g

lemma rightTranslationLinearMap_mem {f : G → ℂ}
    (hf : f ∈ subgroupCharacterFunctionSubmodule H lam) (a : G) :
    rightTranslationLinearMap a f ∈ subgroupCharacterFunctionSubmodule H lam

lemma subgroupCharacterAveraging_eq_self {f : G → ℂ}
    (hf : f ∈ subgroupCharacterFunctionSubmodule H lam) :
    subgroupCharacterAveraging H lam f = f

theorem two_dvd_card_ne_fixed_of_involutive {α : Type*} [Fintype α] [DecidableEq α]
    {f : α → α} (hf : Function.Involutive f) :
    2 ∣ Fintype.card {a // f a ≠ a}

theorem exists_basis_blockTriangular_of_isAlgClosed [IsAlgClosed k] {N : ℕ}
    (A : V →ₗ[k] V) (hN : Module.finrank k V = N) :
    ∃ b : Basis (Fin N) k V, (LinearMap.toMatrix b b A).BlockTriangular id

theorem exists_perm_eq_comp_of_map_univ_eq {N : ℕ} {lam mu : Fin N → k}
    (h : Finset.univ.val.map lam = Finset.univ.val.map mu) :
    ∃ e : Equiv.Perm (Fin N), ∀ i, lam i = mu (e i)

theorem exists_perm_eq_comp_of_prod_X_sub_C_eq {N : ℕ} {lam mu : Fin N → k}
    (h : (∏ i, (X - C (lam i))) = ∏ i, (X - C (mu i))) :
    ∃ e : Equiv.Perm (Fin N), ∀ i, lam i = mu (e i)

theorem discr_ne_zero_iff_separable_of_natDegree_derivative_eq {K : Type*} [Field K] {f : K[X]}
    (hpos : 0 < f.natDegree) (hd : f.derivative.natDegree = f.natDegree - 1) :
    f.discr ≠ 0 ↔ f.Separable

theorem finite_elementProperty_of_finiteDimensional
    (k : Type*) [Field k] [Algebra k R] [FiniteDimensional k R] :
    Finite {e : R // ElementProperty R e}

lemma mul_mem_sandwichSubmodule {e : A} {x y : A}
    (hx : x ∈ sandwichSubmodule (k := k) e) (hy : y ∈ sandwichSubmodule (k := k) e) :
    x * y ∈ sandwichSubmodule (k := k) e
